
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_scanl_rvv10_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_scanl_rvv10", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.650590957695254e-02, -2.645852319946250e-02, -2.638826645370952e-02, -2.628271628918166e-02, -2.612113046957869e-02, -2.586713557016758e-02, -2.547681538434805e-02, -2.535364861402865e-02, -2.464429318513876e-02, -2.449092064538284e-02, -3.040030488630192e-02, -4.678373391295143e-02, -2.817284489752166e-02, -2.446153761231193e-02, -2.009727499313219e-02, -1.522145661302934e-02, -7.781068050029568e-03, -2.695416906877361e-03, -4.824942111530869e-04, -2.760087907208806e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


